fix:
Use rank-based summaries like the median (50th percentile) to describe typical behavior and high percentiles (p95, p99) to capture tail outliers.
```rust
fn report_summary_correct(mut latencies: Vec<f64>) {
    latencies.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let median = latencies[latencies.len() / 2];
    let p99 = latencies[(latencies.len() as f64 * 0.99) as usize];
    println!("Median: {:.2}ms, p99: {:.2}ms", median, p99);
}
